__NUXT_JSONP__("/por/teachers", {data:[{details:{slug:"por",pageTitle:"Classes MLI e professores | Mentor Language Institute",pageDescription:"Nos cursos gerais de inglês, os alunos adquirem habilidades práticas utilizando materiais do mundo real, como postagens do Twitter,  TED talks e clipes de filmes.",title:"Classes MLI e professores",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"As aulas se concentram em Habilidades Práticas",description:["Nos cursos gerais de inglês, os alunos adquirem habilidades práticas utilizando materiais do mundo real, como postagens do Twitter,  TED talks e clipes de filmes. Usando esses materiais, os alunos adquirem sistematicamente padrões de gramática, escrita, leitura, vocabulário, escuta e fala.","Além disso, TOEFL® e outros cursos de preparação para exames fornecem estratégias para resolver problemas com seus próprios métodos."]},{title:"Professores da MLI",description:["1.200 alunos se formam na MLI todos os anos, dos quais falam da qualidade de nossos educadores. Nós nos esforçamos constantemente para melhorar as habilidades dos instrutores através de observações, avaliações e oficinas de desenvolvimento profissional."],checklist:[{title:"Requisitos de contratação (lista de verificação para contratação de professores)",lists:["Pós-graduação de quatro anos","3 anos de experiência como instrutor de inglês","Qualificação de ensino como TESOL","Conhecimento de testes de exame como TOEFL® \u002F GMAT®","Habilidade forte em comunicação","Paixão e compromisso pelo ensino"]},{title:"Método de seleção",lists:["Currículo e diploma","Teste de gramática em Inglês","Entrevista","Lição de Modelo"],note:"A taxa de contratação é inferior a 20%."}]},{title:"Sistema de treinamento e avaliação",description:["Na MLI, verificamos os seguintes três itens, a cada 12 semanas, para manter a qualidade do professor."],listType:"decimal",lists:["Estudantes avaliam livros didáticos e instrutores. Os instrutores com uma taxa de satisfação de 85% ou menos são submetidos a treinamento de desenvolvimento profissional.","Observação de aula e comentários fornecidos pela equipe acadêmica sênior","Oficinas de desenvolvimento profissional e treinamento para melhorar a instrução"],note:"Gestão e instrutores se esforçam para melhorar a qualidade da educação todos os dias!"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:31.177Z",updatedAt:"2025-05-26T12:06:27.931Z"}}],fetch:{},mutations:void 0});